<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api, assetUrl, dateLabel, verdictLabel, verdictClass } from '../api';
import { workspace, currentBoard } from '../workspace';
import EmptyState from '../components/EmptyState.vue';
import StatusBadge from '../components/StatusBadge.vue';
import ReviewContractDetail from '../components/ReviewContractDetail.vue';
import PathViewer from '../components/PathViewer.vue';
const route=useRoute(),router=useRouter();
const reports=ref([]), report=ref(null), loading=ref(false), reportLoading=ref(false), error=ref(''), feedback=ref({}), profiles=ref([]), profileId=ref('');
const runId=ref(''), selectedKey=ref(''), search=ref(''), ruleFilter=ref(String(route.query.rule||'')), verdictFilter=ref(''), reviewFilter=ref(''), mobileTab=ref('issues');
const mark=ref('unreviewed'), note=ref(''), feedbackBusy=ref(false), feedbackNotice=ref(''), question=ref(''), answer=ref(null), asking=ref(false), questionError=ref('');
const viewer=ref(null), pageIndex=ref(0), compareId=ref(''), comparison=ref(null), comparing=ref(false), compareError=ref('');
let boardGen=0,reportGen=0,questionGen=0;
const reportKey=r=>String(r.id||r.run_id||'');
const assetBase=computed(()=>`/reports/${encodeURIComponent(runId.value)}`);
const selectedReport=computed(()=>reports.value.find(r=>reportKey(r)===runId.value));
function cardsFor(data){
 const packs=Array.isArray(data?.evidence)?Object.fromEntries(data.evidence.map(pack=>[pack.rule_id,pack])):data?.evidence||{};
 return (data?.verdicts?.results||[]).flatMap(rule=>{
  const pack=packs[rule.rule_id]||{};
  return (pack.object_cards||rule.object_cards||[]).map(card=>({...card,rule_id:rule.rule_id,rule_title:rule.title||pack.name||rule.rule_id,key:`${rule.rule_id}::${card.object}`,view:card.review_detail||data?.report_data?.review_details?.[rule.rule_id]?.[card.object]}));
 });
}
const allCards=computed(()=>cardsFor(report.value));
const ruleOptions=computed(()=>report.value?.verdicts?.results||[]);
const filtered=computed(()=>allCards.value.filter(card=>{
 const text=`${card.rule_id} ${card.rule_title} ${card.object} ${card.headline_zh||card.conclusion||card.summary||''}`.toLowerCase();
 const state=feedback.value[card.key]?.mark||'unreviewed';
 return (!search.value||text.includes(search.value.toLowerCase()))&&(!ruleFilter.value||card.rule_id===ruleFilter.value)&&(!verdictFilter.value||verdictLabel(card.verdict_zh)===verdictFilter.value)&&(!reviewFilter.value||state===reviewFilter.value);
}));
const selected=computed(()=>allCards.value.find(card=>card.key===selectedKey.value));
const pages=computed(()=>selected.value?.view?.resources?.pages||[]);
const selectedPage=computed(()=>pages.value[pageIndex.value]||pages.value[0]);
const pdfUrl=computed(()=>{const page=selectedPage.value;if(!page?.pdf)return '';return assetUrl(assetBase.value,'pdfjs/web/viewer.html')+'?file='+encodeURIComponent(assetUrl(assetBase.value,page.pdf))+'#page='+(page.page||1);});
const countByVerdict=computed(()=>allCards.value.reduce((counts,card)=>{const label=verdictLabel(card.verdict_zh);counts[label]=(counts[label]||0)+1;return counts;},{}));
const feedbackLabels={unreviewed:'未复核',confirmed:'已确认',disputed:'有异议'};
const changes=computed(()=>{
 if(!comparison.value)return [];
 const before=new Map(cardsFor(comparison.value).map(card=>[card.key,card]));const after=new Map(allCards.value.map(card=>[card.key,card]));
 return [...new Set([...before.keys(),...after.keys()])].flatMap(key=>{
  const prev=before.get(key),next=after.get(key);
  if(prev&&next&&prev.verdict_zh===next.verdict_zh)return [];
  return [{key,rule_id:(next||prev).rule_id,object:(next||prev).object,before:prev?verdictLabel(prev.verdict_zh):'未纳入',after:next?verdictLabel(next.verdict_zh):'未纳入'}];
 });
});
async function loadBoardsReports(){const id=workspace.boardId,token=++boardGen;reportGen++;questionGen++;reports.value=[];report.value=null;runId.value='';feedback.value={};comparison.value=null;compareId.value='';error.value='';if(!id)return;loading.value=true;try{const [data,pp]=await Promise.all([api.reports(id),api.profiles()]);if(token!==boardGen)return;reports.value=data.reports||[];profiles.value=pp.profiles||[];profileId.value=pp.default_profile_id||profiles.value[0]?.id||'';const desired=String(route.query.run||'');const target=reports.value.find(r=>reportKey(r)===desired)||reports.value[0];if(target)await loadReport(reportKey(target));else if(desired)await loadReport(desired);}catch(e){if(token===boardGen)error.value=e.message;}finally{if(token===boardGen)loading.value=false;}}
async function loadReport(id){const token=++reportGen;questionGen++;reportLoading.value=true;report.value=null;runId.value=id;selectedKey.value='';feedback.value={};comparison.value=null;compareId.value='';answer.value=null;question.value='';error.value='';try{const [data,fb]=await Promise.all([api.report(id),api.feedback(id)]);if(token!==reportGen)return;report.value=data;feedback.value=fb.feedback||{};const desired=route.query.rule&&route.query.object?`${route.query.rule}::${route.query.object}`:'';selectedKey.value=allCards.value.some(c=>c.key===desired)?desired:allCards.value.find(c=>!ruleFilter.value||c.rule_id===ruleFilter.value)?.key||allCards.value[0]?.key||'';}catch(e){if(token===reportGen)error.value=e.message;}finally{if(token===reportGen)reportLoading.value=false;}}
watch(()=>workspace.boardId,loadBoardsReports,{immediate:true});
watch(()=>route.query.run,id=>{if(id&&id!==runId.value&&!loading.value)loadReport(String(id));});
watch(()=>[route.query.rule,route.query.object],()=>{const key=`${route.query.rule}::${route.query.object}`;if(!route.query.object||key!==selectedKey.value)ruleFilter.value=String(route.query.rule||'');if(allCards.value.some(c=>c.key===key))selectedKey.value=key;});
watch(selectedKey,()=>{pageIndex.value=0;questionGen++;asking.value=false;question.value='';answer.value=null;questionError.value='';feedbackNotice.value='';const value=feedback.value[selectedKey.value];mark.value=value?.mark||'unreviewed';note.value=value?.note||'';});
watch(filtered,list=>{if(list.length&&!list.some(c=>c.key===selectedKey.value))selectedKey.value=list[0].key;});
function select(card){selectedKey.value=card.key;router.replace({path:'/reports',query:{board:workspace.boardId,run:runId.value,rule:card.rule_id,object:card.object}});mobileTab.value='detail';}
function changeReport(event){router.replace({path:'/reports',query:{board:workspace.boardId,run:event.target.value}});}
async function saveFeedback(){const card=selected.value;if(!card)return;const key=card.key,run=runId.value;feedbackBusy.value=true;feedbackNotice.value='';try{const payload={mark:mark.value,note:note.value};const value=await api.saveFeedback(run,card.rule_id,card.object,payload);if(run===runId.value){feedback.value={...feedback.value,[key]:value.feedback||value.record||value};if(selectedKey.value===key)feedbackNotice.value='复核意见已保存。';}}catch(e){error.value=e.message;}finally{feedbackBusy.value=false;}}
async function ask(){const card=selected.value;if(!card||!question.value.trim())return;const token=++questionGen;asking.value=true;answer.value=null;questionError.value='';try{const data=await api.ask(runId.value,card.rule_id,card.object,{question:question.value.trim(),profile_id:profileId.value||null});if(token===questionGen)answer.value=data;}catch(e){if(token===questionGen)questionError.value=e.message;}finally{if(token===questionGen)asking.value=false;}}
async function compare(){comparison.value=null;compareError.value='';if(!compareId.value)return;comparing.value=true;const id=compareId.value;try{const data=await api.report(id);if(compareId.value===id)comparison.value=data;}catch(e){compareError.value=e.message;}finally{comparing.value=false;}}
async function rerun(){if(!selected.value)return;const card=selected.value;router.push({path:'/runs',query:{board:workspace.boardId,rule:card.rule_id,object:card.object,mode:'review'}});}
function openPath(state){const p=state.figure_pages?.length?state.figure_pages:state.figure?[{src:state.figure,label:state.title||''}]:[];viewer.value={pages:p.map(row=>({...row,src:assetUrl(assetBase.value,row.src||row.figure)})),lines:(state.calculations||[]).map(c=>({expr:c.expression,src:''})),who:`${selected.value.rule_id} / ${selected.value.object}`};}
onBeforeUnmount(()=>{boardGen++;reportGen++;questionGen++;});
</script>
<template>
  <EmptyState v-if="!workspace.boardId&&!workspace.loading" title="先选择一个项目" description="在项目中完成一次评审后，可在这里核对问题与证据。"><router-link class="button primary" to="/">前往项目</router-link></EmptyState>
  <section v-else class="report-workspace">
    <div class="page-heading report-heading"><div><div class="eyebrow">REVIEW WORKBENCH</div><h1>核对每一个判定</h1><p>{{ currentBoard?.name }} · 选择对象，查看原理图、来源与分析，再记录你的复核意见。</p></div><div class="actions"><router-link class="button" :to="{path:'/runs',query:{board:workspace.boardId}}">新建评审</router-link><a v-if="report" class="button" :href="assetUrl(assetBase,'expert_review.html')" target="_blank" rel="noopener">打开完整报告 ↗</a></div></div>
    <div v-if="error" class="notice error" role="alert">{{ error }}<button class="button small" @click="loadBoardsReports">重新加载</button></div>
    <div v-if="loading||reportLoading" class="loading-state" aria-live="polite">正在加载完整评审报告</div>
    <EmptyState v-else-if="!report&&!error" title="还没有已发布的报告" description="从运行页面选择检查范围并启动任务。完成校验的报告会出现在这里，未完成结果不会覆盖已有报告。"><router-link class="button primary" :to="{path:'/runs',query:{board:workspace.boardId}}">开始一次评审</router-link></EmptyState>
    <template v-else-if="report"><div class="report-toolbar"><div class="report-selector"><label for="report-version">评审批次</label><select id="report-version" :value="runId" @change="changeReport"><option v-for="r in reports" :key="reportKey(r)" :value="reportKey(r)">{{ r.title || dateLabel(r.finished_at||r.created_at) }} · {{ reportKey(r).slice(0,8) }}</option><option v-if="!selectedReport" :value="runId">{{ runId.slice(0,12) }}</option></select></div><div class="report-counts"><span v-for="label in ['通过','不通过','待确认','不适用']" :key="label"><StatusBadge :tone="verdictClass(label)">{{ label }} {{ countByVerdict[label]||0 }}</StatusBadge></span></div><span class="report-object-count">{{ allCards.length }} 个对象判定</span></div>
      <details class="report-history"><summary>历史比较与导出</summary><div class="history-content"><div class="actions"><label for="compare-report">与历史批次比较</label><select id="compare-report" v-model="compareId" @change="compare"><option value="">选择已发布报告</option><option v-for="r in reports.filter(r=>reportKey(r)!==runId)" :key="reportKey(r)" :value="reportKey(r)">{{ dateLabel(r.finished_at||r.created_at) }} · {{ reportKey(r).slice(0,8) }}</option></select><a class="button small primary" :href="`/api/reports/${encodeURIComponent(runId)}/download`" download>下载完整报告包</a><a class="button small" :href="assetUrl(assetBase,'report_data.json')" download>下载报告数据</a><a class="button small" :href="assetUrl(assetBase,'expert_review.html')" download>下载 HTML</a></div><p class="inline-note">比较同一规则与对象的工程结论；“未纳入”表示该次报告未覆盖此对象。HTML 的图纸和附件可在本机工作台中查看。</p><p v-if="comparing" class="small-copy muted">正在读取历史报告…</p><div v-if="compareError" class="notice error">{{ compareError }}</div><div v-if="comparison" class="data-table-wrap"><table v-if="changes.length" class="data-table"><thead><tr><th>检查项</th><th>对象</th><th>历史结论</th><th>本次结论</th></tr></thead><tbody><tr v-for="change in changes" :key="change.key"><td>{{ change.rule_id }}</td><td>{{ change.object }}</td><td>{{ change.before }}</td><td>{{ change.after }}</td></tr></tbody></table><p v-else class="small-copy">两次报告中，同一规则与对象的工程结论没有变化。</p></div></div></details>
      <nav class="inline-tabs report-mobile-tabs" aria-label="工作区视图"><button v-for="(label,key) in {issues:'问题清单',drawing:'原理图',detail:'分析与复核'}" :key="key" :class="{active:mobileTab===key}" @click="mobileTab=key">{{ label }}</button></nav>
      <div class="review-columns" :data-mobile-tab="mobileTab"><aside class="issues-pane"><div class="pane-heading"><h2>问题清单</h2><span>{{ filtered.length }} / {{ allCards.length }}</span></div><div class="issue-filters"><label class="sr-only" for="object-search">搜索对象或问题</label><input id="object-search" v-model="search" class="search-input" placeholder="搜索位号、规则或问题" /><label class="sr-only" for="rule-filter">筛选检查项</label><select id="rule-filter" v-model="ruleFilter"><option value="">全部检查项</option><option v-for="rule in ruleOptions" :key="rule.rule_id" :value="rule.rule_id">{{ rule.rule_id }} · {{ rule.title }}</option></select><div><label class="sr-only" for="verdict-filter">筛选结论</label><select id="verdict-filter" v-model="verdictFilter"><option value="">全部结论</option><option v-for="label in ['通过','不通过','待确认','不适用']" :key="label">{{ label }}</option></select><label class="sr-only" for="review-filter">筛选复核状态</label><select id="review-filter" v-model="reviewFilter"><option value="">全部复核状态</option><option v-for="(label,key) in feedbackLabels" :key="key" :value="key">{{ label }}</option></select></div></div><div class="issue-list"><button v-for="card in filtered" :key="card.key" class="issue-row" :class="{selected:card.key===selectedKey}" @click="select(card)" :aria-pressed="card.key===selectedKey"><div class="issue-row-top"><strong>{{ card.object }}</strong><StatusBadge :tone="verdictClass(card.verdict_zh)">{{ verdictLabel(card.verdict_zh) }}</StatusBadge></div><span class="issue-rule">{{ card.rule_id }} · {{ card.rule_title }}</span><p>{{ card.headline_zh||card.conclusion||card.summary||'打开查看评审依据' }}</p><small>{{ feedbackLabels[feedback[card.key]?.mark]||'未复核' }}</small></button><p v-if="!filtered.length" class="no-filter-results">没有匹配的对象，试试调整筛选条件。</p></div></aside>
      <section class="drawing-pane"><div class="pane-heading"><h2>原理图</h2><a v-if="pdfUrl" :href="pdfUrl" target="_blank" rel="noopener">独立窗口 ↗</a></div><div v-if="pages.length" class="drawing-controls"><label for="schematic-page">关联图幅</label><select id="schematic-page" v-model="pageIndex"><option v-for="(page,index) in pages" :key="index" :value="index">第 {{ page.page }} 页{{ page.title?' · '+page.title:'' }}</option></select><span>{{ selected?.object }}</span></div><iframe v-if="pdfUrl" :key="pdfUrl" :src="pdfUrl" :title="`${selected?.object} 的关联原理图第 ${selectedPage?.page} 页`"></iframe><EmptyState v-else title="当前对象尚未关联图幅" description="这里展示报告中已有的可靠定位。可以先在右侧核对材料与证据。" /></section>
      <section class="analysis-pane"><div class="pane-heading"><h2>{{ selected?.object||'对象详情' }} <span v-if="selected">{{ selected.rule_id }}</span></h2><StatusBadge v-if="selected" :tone="verdictClass(selected.verdict_zh)">{{ verdictLabel(selected.verdict_zh) }}</StatusBadge></div><div v-if="selected" class="analysis-content"><ReviewContractDetail v-if="selected.view" :view="selected.view" :asset-base="assetBase" :source-assets="report.source_assets || {}" @open-path="openPath" /><div v-else class="notice warning">这份报告尚未生成统一分析详情。请在运行页重新生成完整报告。</div>
      <form class="feedback-panel" @submit.prevent="saveFeedback"><h3>人工复核</h3><p>复核意见独立记录，保留原始工程判定。</p><div class="feedback-options"><label v-for="(label,key) in feedbackLabels" :key="key"><input type="radio" name="review-mark" v-model="mark" :value="key" />{{ label }}</label></div><label class="sr-only" for="feedback-note">复核意见</label><textarea id="feedback-note" v-model="note" rows="3" placeholder="记录核查依据、疑问或需要补充的材料" maxlength="10000"></textarea><div class="actions"><button class="button small primary" :disabled="feedbackBusy">{{ feedbackBusy?'保存中…':'保存复核意见' }}</button><span v-if="feedbackNotice" class="save-notice" role="status">{{ feedbackNotice }}</span></div></form>
      <details class="question-panel"><summary>围绕此对象追问</summary><p>回答基于本次报告与证据，追问不会修改原始判定。</p><div v-if="!profiles.length" class="notice warning">请先在<router-link to="/models">模型设置</router-link>中配置服务。</div><form @submit.prevent="ask"><div class="field"><label for="question-profile">使用模型</label><select id="question-profile" v-model="profileId"><option v-for="p in profiles" :key="p.id" :value="p.id">{{ p.name||p.model }}</option></select></div><label class="sr-only" for="object-question">针对当前对象的问题</label><textarea id="object-question" v-model="question" rows="3" placeholder="例如：这个结论依赖哪些材料？还有哪些条件需要确认？" required></textarea><div class="actions"><button class="button small" :disabled="asking||!profileId||!question.trim()">{{ asking?'正在分析…':'发送问题' }}</button><button class="button small ghost" type="button" @click="rerun">设置此对象复核 →</button></div></form><div v-if="questionError" class="notice error" role="alert">{{ questionError }}</div><div v-if="answer" class="question-answer"><p>{{ answer.answer||answer.text }}</p><ul v-if="answer.citations?.length"><li v-for="(citation,index) in answer.citations" :key="index">{{ typeof citation==='string'?citation:[citation.source_id||citation.label||citation.source,citation.quote].filter(Boolean).join(' · ')||JSON.stringify(citation) }}</li></ul></div></details>
      </div><EmptyState v-else title="选择一个对象" description="从问题清单中选择对象，查看它的分析与复核记录。" /></section></div>
    </template>
    <PathViewer v-if="viewer" :pages="viewer.pages" :lines="viewer.lines" :who="viewer.who" @close="viewer=null" />
  </section>
</template>
<style scoped>
